use std::{
    env, fs,
    io::Write,
    path::{Path, PathBuf},
};

use directories::BaseDirs;
use serde::Serialize;
use tempfile::NamedTempFile;

use crate::args::SkillTarget;

// `SKILL_FILES`: (Skill directory, path relative to it, contents) for every bundled Skill
// file, sorted by Skill and path; generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/skill_files.rs"));

/// Codex interface metadata, which Claude Code does not use.
const OPENAI_METADATA: &str = "agents/openai.yaml";

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Agent {
    Codex,
    Claude,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum InstallStatus {
    Installed,
    Updated,
    Unchanged,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct InstallResult {
    pub agent: Agent,
    pub skill: String,
    pub path: String,
    pub status: InstallStatus,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct InstallTarget {
    agent: Agent,
    /// The agent's skills directory; each Skill goes into a subdirectory named after it.
    directory: PathBuf,
}

pub fn install(target: SkillTarget) -> Result<Vec<InstallResult>, String> {
    let home = env::var_os("HOME")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .or_else(|| BaseDirs::new().map(|directories| directories.home_dir().to_path_buf()));
    let claude_config = env::var_os("CLAUDE_CONFIG_DIR")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from);
    let targets = resolve_targets(target, home.as_deref(), claude_config.as_deref())?;

    install_targets(&targets)
}

fn resolve_targets(
    target: SkillTarget,
    home: Option<&Path>,
    claude_config: Option<&Path>,
) -> Result<Vec<InstallTarget>, String> {
    let home = home.filter(|path| !path.as_os_str().is_empty());
    let claude_config = claude_config.filter(|path| !path.as_os_str().is_empty());

    match target {
        SkillTarget::All => {
            let home = required_home(home, Agent::Codex)?;
            Ok(vec![codex_target(home), claude_target(home, claude_config)])
        }
        SkillTarget::Codex => Ok(vec![codex_target(required_home(home, Agent::Codex)?)]),
        SkillTarget::Claude => {
            let directory = match claude_config {
                Some(config) => config.join("skills"),
                None => required_home(home, Agent::Claude)?.join(".claude/skills"),
            };
            Ok(vec![InstallTarget {
                agent: Agent::Claude,
                directory,
            }])
        }
    }
}

fn required_home(home: Option<&Path>, agent: Agent) -> Result<&Path, String> {
    home.ok_or_else(|| {
        format!(
            "could not determine the home directory required for {} Skill installation",
            agent.name()
        )
    })
}

fn codex_target(home: &Path) -> InstallTarget {
    InstallTarget {
        agent: Agent::Codex,
        directory: home.join(".agents/skills"),
    }
}

fn claude_target(home: &Path, claude_config: Option<&Path>) -> InstallTarget {
    InstallTarget {
        agent: Agent::Claude,
        directory: claude_config
            .map(|config| config.join("skills"))
            .unwrap_or_else(|| home.join(".claude/skills")),
    }
}

fn install_targets(targets: &[InstallTarget]) -> Result<Vec<InstallResult>, String> {
    targets
        .iter()
        .flat_map(|target| {
            SKILL_FILES
                .chunk_by(|left, right| left.0 == right.0)
                .map(move |files| install_skill(target, files))
        })
        .collect()
}

fn install_skill(
    target: &InstallTarget,
    files: &[(&str, &str, &[u8])],
) -> Result<InstallResult, String> {
    let (skill, _, _) = files[0];
    let directory = target.directory.join(skill);
    let skill_was_present = path_exists(&directory.join("SKILL.md"))?;
    let mut changes = Vec::new();

    for &(_, relative_path, contents) in files {
        if !target.agent.receives(relative_path) {
            continue;
        }
        let path = directory.join(relative_path);
        match fs::read(&path) {
            Ok(existing) if existing == contents => {}
            Ok(_) => changes.push((path, contents)),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                changes.push((path, contents));
            }
            Err(error) => return Err(path_error("read", &path, &error)),
        }
    }

    let status = if changes.is_empty() {
        InstallStatus::Unchanged
    } else if skill_was_present {
        InstallStatus::Updated
    } else {
        InstallStatus::Installed
    };
    for (path, contents) in changes {
        let parent = path.parent().ok_or_else(|| {
            format!(
                "managed Skill file has no parent directory: {}",
                path.display()
            )
        })?;
        fs::create_dir_all(parent)
            .map_err(|error| path_error("create directory for", &path, &error))?;
        atomic_write(&path, contents)?;
    }

    Ok(InstallResult {
        agent: target.agent,
        skill: skill.to_owned(),
        path: directory.to_string_lossy().into_owned(),
        status,
    })
}

fn path_exists(path: &Path) -> Result<bool, String> {
    match fs::metadata(path) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(path_error("inspect", path, &error)),
    }
}

fn atomic_write(path: &Path, contents: &[u8]) -> Result<(), String> {
    let parent = path.parent().ok_or_else(|| {
        format!(
            "managed Skill file has no parent directory: {}",
            path.display()
        )
    })?;
    let mut temporary = NamedTempFile::new_in(parent)
        .map_err(|error| path_error("create temporary file for", path, &error))?;
    temporary
        .write_all(contents)
        .map_err(|error| path_error("write", path, &error))?;
    temporary
        .flush()
        .map_err(|error| path_error("flush", path, &error))?;
    temporary
        .persist(path)
        .map_err(|error| path_error("persist", path, &error.error))?;
    Ok(())
}

fn path_error(action: &str, path: &Path, error: &std::io::Error) -> String {
    format!("failed to {action} {}: {error}", path.display())
}

impl Agent {
    fn name(self) -> &'static str {
        match self {
            Self::Codex => "Codex",
            Self::Claude => "Claude",
        }
    }

    /// Codex receives every bundled file; Claude Code skips Codex's interface metadata.
    fn receives(self, relative_path: &str) -> bool {
        self == Self::Codex || relative_path != OPENAI_METADATA
    }
}

#[cfg(test)]
mod tests {
    use std::{fs, path::Path};

    use serde_json::json;

    use crate::args::SkillTarget;

    use super::{
        Agent, InstallStatus, OPENAI_METADATA, SKILL_FILES, install_targets, resolve_targets,
    };

    /// Embedded Skill names, sorted.
    fn skills() -> Vec<&'static str> {
        let mut skills: Vec<_> = SKILL_FILES.iter().map(|file| file.0).collect();
        skills.dedup();
        skills
    }

    #[test]
    fn all_resolves_codex_then_claude_under_home() {
        let home = Path::new("/home/tester");

        let targets = resolve_targets(SkillTarget::All, Some(home), None).unwrap();

        assert_eq!(targets.len(), 2);
        assert_eq!(targets[0].agent, Agent::Codex);
        assert_eq!(targets[0].directory, home.join(".agents/skills"));
        assert_eq!(targets[1].agent, Agent::Claude);
        assert_eq!(targets[1].directory, home.join(".claude/skills"));
    }

    #[test]
    fn claude_config_directory_works_without_home() {
        let config = Path::new("/custom/claude");

        let targets = resolve_targets(SkillTarget::Claude, None, Some(config)).unwrap();

        assert_eq!(targets.len(), 1);
        assert_eq!(targets[0].agent, Agent::Claude);
        assert_eq!(targets[0].directory, config.join("skills"));
    }

    #[test]
    fn missing_required_home_errors_before_writing() {
        let claude_config = tempfile::tempdir().unwrap();

        let error = resolve_targets(SkillTarget::All, None, Some(claude_config.path()))
            .expect_err("Codex requires a home directory");

        assert!(
            error.contains("home directory"),
            "unexpected error: {error}"
        );
        assert!(!claude_config.path().join("skills").exists());
    }

    #[test]
    fn install_reports_installed_updated_then_unchanged() {
        let home = tempfile::tempdir().unwrap();
        let targets = resolve_targets(SkillTarget::Codex, Some(home.path()), None).unwrap();
        let statuses = || {
            install_targets(&targets)
                .unwrap()
                .into_iter()
                .map(|result| (result.skill, result.status))
                .collect::<Vec<_>>()
        };

        let installed = statuses();
        assert_eq!(installed.len(), skills().len());
        assert!(
            installed
                .iter()
                .all(|(_, status)| *status == InstallStatus::Installed)
        );
        fs::write(targets[0].directory.join("mongodb-cli/SKILL.md"), "stale").unwrap();
        for (skill, status) in statuses() {
            let expected = if skill == "mongodb-cli" {
                InstallStatus::Updated
            } else {
                InstallStatus::Unchanged
            };
            assert_eq!(status, expected, "{skill}");
        }
        assert!(
            statuses()
                .iter()
                .all(|(_, status)| *status == InstallStatus::Unchanged)
        );
    }

    #[test]
    fn install_preserves_unmanaged_files() {
        let home = tempfile::tempdir().unwrap();
        let targets = resolve_targets(SkillTarget::Codex, Some(home.path()), None).unwrap();
        let notes = targets[0].directory.join("mongodb-cli/notes.txt");
        let other_skill = targets[0].directory.join("other/SKILL.md");
        for path in [&notes, &other_skill] {
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, "keep me").unwrap();
        }

        install_targets(&targets).unwrap();

        assert_eq!(fs::read_to_string(notes).unwrap(), "keep me");
        assert_eq!(fs::read_to_string(other_skill).unwrap(), "keep me");
    }

    #[test]
    fn installs_every_file_for_codex_and_all_but_openai_metadata_for_claude() {
        let home = tempfile::tempdir().unwrap();
        let targets = resolve_targets(SkillTarget::All, Some(home.path()), None).unwrap();

        install_targets(&targets).unwrap();

        for expected in ["SKILL.md", OPENAI_METADATA] {
            assert!(
                SKILL_FILES
                    .iter()
                    .any(|file| (file.0, file.1) == ("mongodb-cli", expected)),
                "mongodb-cli/{expected} is not embedded"
            );
        }
        for &(skill, relative_path, contents) in SKILL_FILES {
            let codex = targets[0].directory.join(skill).join(relative_path);
            assert_eq!(
                fs::read(codex).unwrap(),
                contents,
                "{skill}/{relative_path}"
            );
            let claude = targets[1].directory.join(skill).join(relative_path);
            if relative_path == OPENAI_METADATA {
                assert!(!claude.exists(), "{skill}/{relative_path}");
            } else {
                assert_eq!(
                    fs::read(claude).unwrap(),
                    contents,
                    "{skill}/{relative_path}"
                );
            }
        }
    }

    #[test]
    fn results_serialize_as_expected_objects() {
        let home = tempfile::tempdir().unwrap();
        let targets = resolve_targets(SkillTarget::All, Some(home.path()), None).unwrap();

        let value = serde_json::to_value(install_targets(&targets).unwrap()).unwrap();

        let expected: Vec<_> = targets
            .iter()
            .flat_map(|target| {
                skills().into_iter().map(move |skill| {
                    json!({
                        "agent": target.agent,
                        "skill": skill,
                        "path": target.directory.join(skill).to_str(),
                        "status": "installed",
                    })
                })
            })
            .collect();
        assert_eq!(value, json!(expected));
        assert_eq!(
            value[0].as_object().unwrap().keys().collect::<Vec<_>>(),
            ["agent", "skill", "path", "status"]
        );
    }

    #[cfg(unix)]
    #[test]
    fn result_path_serializes_when_target_path_is_not_utf8() {
        use std::{ffi::OsString, os::unix::ffi::OsStringExt};

        let root = tempfile::tempdir().unwrap();
        let home = root
            .path()
            .join(OsString::from_vec(vec![b'h', b'o', b'm', b'e', 0xff]));
        let targets = resolve_targets(SkillTarget::Codex, Some(&home), None).unwrap();

        #[cfg(not(target_os = "macos"))]
        let results = install_targets(&targets).unwrap();

        // macOS rejects invalid UTF-8 in filesystem operations, so install into
        // the valid temporary root before exercising the resolved report path.
        #[cfg(target_os = "macos")]
        let results = {
            use std::path::PathBuf;

            trait ReportPathForTest {
                fn from_directory(directory: &Path) -> Self;
            }

            impl ReportPathForTest for PathBuf {
                fn from_directory(directory: &Path) -> Self {
                    directory.to_path_buf()
                }
            }

            impl ReportPathForTest for String {
                fn from_directory(directory: &Path) -> Self {
                    directory.to_string_lossy().into_owned()
                }
            }

            let install_targets_resolved =
                resolve_targets(SkillTarget::Codex, Some(root.path()), None).unwrap();
            let mut results = install_targets(&install_targets_resolved).unwrap();
            results[0].path =
                ReportPathForTest::from_directory(&targets[0].directory.join(&results[0].skill));
            results
        };

        let value = serde_json::to_value(&results)
            .expect("reported paths use a guaranteed UTF-8 representation");

        assert!(value[0]["path"].is_string());
        assert_eq!(
            value[0]["path"].as_str(),
            Some(
                targets[0]
                    .directory
                    .join(&results[0].skill)
                    .to_string_lossy()
                    .as_ref()
            )
        );
    }
}
